using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.FiniteGroups.GroupAlgebra;

internal sealed class CyclicNormOneDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "A finite telescope lifts norm one in a noncommutative ring without a period hypothesis.",
        H("Cyclic Norm-One Lifting"),
        Blocks(Describe.Lean(
            DescribeId.Create("cyclic-norm-one-lift"),
            DeclarationHandle.Create("D5/S3/FiniteGroups/GroupAlgebra/CyclicNormOne.exists_norm_one_lift"),
            H("From a step norm to the full norm"),
            StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text("Let A be any unital ring, possibly noncommutative or the zero ring, and let sigma be a ring automorphism of A. Let q, r and c be natural numbers with 0 < q, 0 < r and r = c*q. If the sum of sigma^(q*i)(x) over 0 <= i < r equals 1, there exists y in A such that the sum of sigma^k(y) over 0 <= k < q*r equals 1. There is no assumption that sigma has finite order. There is no commutativity, nontriviality, characteristic, nilpotence, scalar invertibility, ring finiteness or finite-generation assumption. Positivity of q also follows from positive r and r = c*q.")),
                Paragraph(Text("Write tau = sigma^q, T(a) = sum over i < r of tau^i(a), and S(a) = sum over j < q of sigma^j(a). The supplied hypothesis is T(x) = 1. Define z = c times S(x) minus 1, where multiplication by c is natural additive scalar multiplication. Define w = sum over i < r of the sum over j < i of tau^j(x * (tau^i).symm(z)). Define b = c times x + w - sigma(w) and y = b*x. These are actual finite sums in A. In the inner product defining w, x is the left factor and the inverse image of z is the right factor. In y, x is the right factor. No factors are commuted.")),
                Paragraph(Text("Automorphism powers commute under composition, so T(S(x)) = S(T(x)). Ring automorphisms preserve 1 and natural additive scalar multiplication. Consequently T(z) = c times S(T(x)) minus r times 1 = c*q times 1 minus r times 1 = 0. The existing additive norm and the original norm_comm and norm_blocks APIs are exposed for CyclicSubgroupProjectivity.projective_iff_projective_prime_support_subgroup; their statements and proofs remain at this owner.")),
                Paragraph(Text("The inverse norm is sum over i < r of (tau^i).symm(z). It equals (tau^(r-1)).symm(T(z)): applying tau^(r-1) gives the sum of tau^(r-1-i)(z), and Finset.sum_range_reflect identifies this reflected sum with T(z). For i < r, the inequality i <= r-1 justifies the natural-exponent identity tau^(r-1) = tau^(r-1-i) * tau^i. Thus the inverse norm is zero. No replacement of an inverse power by a positive power modulo a group order occurs, so neither tau^r = 1 nor sigma^(q*r) = 1 is required.")),
                Paragraph(Text("For each i, applying tau minus the identity to the inner sum defining w telescopes to tau^i(x * (tau^i).symm(z)) minus x * (tau^i).symm(z). Its first term is tau^i(x)*z. Summing in i gives tau(w) - w = T(x)*z - x*inverseNorm(z) = z. The inner sums telescope before the two outer products are distributed.")),
                Paragraph(Text("The same telescope gives sigma(S(x)) - S(x) = tau(x) - x, hence sigma(z) - z = c times (tau(x) - x). Since tau commutes with sigma, substitute tau(w) = w + z into tau(b). The two difference identities cancel and give tau(b) = b. Next S(b) = c times S(x) + S(w) - S(sigma(w)). Commutation of the automorphism powers identifies S(sigma(w)) with sigma(S(w)); the finite telescope then gives S(sigma(w)) - S(w) = tau(w) - w = z. It follows that S(b) = c times S(x) - z = 1.")),
                Paragraph(Text("Invariance of b gives tau^i(b) = b for every natural i, so T(b*x) = b*T(x) = b, with b factored only on the left. The full sigma sum of length q*r equals S(T(a)): split the range into consecutive blocks k = q*i+j, use automorphism power addition, and commute the two powers under composition. Applied to a = b*x, the full norm is S(T(b*x)) = S(b) = 1.")),
                Paragraph(Text("For the prime-support detector over any finite cyclic group, strong induction on the subgroup index applies this lift one prime factor at a time; CyclicSubgroupProjectivity supplies the actual subgroup and conjugation-norm identifications. In the prime-power case of order p^k, where p is prime and k >= 2, take q = p, r = p^(k-1), c = p^(k-2). Then r = c*q and q*r = p^k. The subgroup generated by g^p has order p^(k-1); the theorem lifts a norm-one element for its action to one for the whole group. Repeating this step from the subgroup of order p is the intended detection route, with the k = 1 case requiring no lift. For a representation rho on an arbitrary R-module M, use A = End_R(M), ring multiplication given by composition, and sigma(f) = rho(g) composed with f composed with rho(g)^(-1). This endomorphism ring is generally noncommutative. No finite-generation hypothesis on M enters this ring identity.")),
                Paragraph(Text("A norm-one endomorphism provides the trace input for relative projectivity with respect to the coefficient ring. For absolute projectivity over R[C_(p^k)], M must additionally be projective as an R-module: relative splitting can then be applied to an R-linear section of an epimorphism onto M. Absolute group-algebra projectivity also implies coefficient projectivity by restriction. Without that extra condition the inference is false; for example, the trivial group already has identity norm on End_R(M) for every M, including nonprojective R-modules.")),
                Paragraph(Text("The construction is adapted from E. Aljadeff and C. Kassel, Explicit elements of norm one for cyclic groups, https://arxiv.org/abs/math/0012038, particularly the Theorem and Lemmas 1-3. The period-free formulation uses the finite reflection identity above; the cited paper is not asserted to state this formulation verbatim."))),
            DescribeRole.Theorem))));
}
